g = json.load(open(F, encoding='utf-8'))
ids = {x['id'] for x in g}
terminos = {x['termino'].lower() for x in g}
n = 0
for sig, sign, ex, ref in S:
    i = 'sigla-' + sig.lower().replace('/', '-')
    if i in ids or sig.lower() in terminos or sig.lower() in ids: continue
    g.append({'id': i, 'termino': sig, 'tipo': 'sigla', 'def': f'{sign}. {ex}', 'ejemplo': '', 'ref': ref})
    n += 1
json.dump(g, open(F, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('siglas añadidas', n, 'total glosario', len(g))
